import sys
import json
import requests
import re

def evaluate_expression(expr, variables):
    # Replace variables with their values
    for var, val in variables.items():
        expr = expr.replace(var, str(val))

    # Tokenize the expression into numbers, variables, and operators
    tokens = re.findall(r'(\d+|\+|\*|[a-zA-Z_]\w*)', expr)
    tokens = [t for t in tokens if t not in ('+', '*')]  # Remove operators temporarily

    # Evaluate each token as a number or variable
    try:
        num_tokens = [int(t) for t in tokens if t.isdigit()]
        var_tokens = [t for t in tokens if not t.isdigit()]
    except ValueError:
        return 0  # Fallback if parsing fails

    # Reconstruct the expression with operators
    expr_with_ops = []
    for i, token in enumerate(tokens):
        if i < len(tokens) - 1 and tokens[i+1] in ('+', '*'):
            expr_with_ops.append(token)
            expr_with_ops.append(tokens[i+1])
        else:
            expr_with_ops.append(token)

    # Evaluate the expression safely
    try:
        return eval(' '.join(expr_with_ops), {}, variables)
    except:
        return 0

def main():
    url = sys.argv[1]
    template_path = sys.argv[2]

    # Fetch JSON data from URL
    response = requests.get(url)
    if response.status_code != 200:
        sys.exit(1)
    data = response.json()

    # Read template file
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    # Replace all {{ expr }} with evaluated expressions
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr, data))

    processed_template = re.sub(r'\{\{([^}]+)\}\}', replace_match, template)
    print(processed_template)

if __name__ == "__main__":
    main()
